// work.staff.list — E5 AC2: who can be @mentioned. Generated by `pnpm gen:query`; guard case kept,
// acceptance case added.
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { aClientActor, aStaffActor } from '@ocs/testing';
import { Forbidden } from '../../kernel/index.ts';
import { staffList } from '../queries/staff-list.ts';
import { openWorkWorld, type WorkWorld } from './fixture.ts';

const allowed = aStaffActor();
const other = aStaffActor();
let w: WorkWorld;

beforeAll(async () => {
  w = await openWorkWorld();
  w.t.grant(allowed, staffList.permission);
  await w.account(allowed);
  await w.account(aStaffActor(), true);
  await w.account(aClientActor('00000000-0000-4000-8000-00000000000a'));
});

afterAll(async () => {
  await w.close();
});

describe('work.staff.list', () => {
  it('refuses an actor without the permission', async () => {
    await expect(w.t.kernel.read(staffList, other, {})).rejects.toBeInstanceOf(Forbidden);
  });

  it('lists active staff by id and name only — no archived staff, no client or partner accounts', async () => {
    expect(await w.t.kernel.read(staffList, allowed, {})).toEqual([{ id: allowed.id, name: 'Person' }]);
  });
});
